{
  "schemaVersion": "0.2",
  "slug": "kpi-dashboard",
  "name": "KpiDashboard",
  "family": "F",
  "status": "experimental",
  "purpose": "Arranges a set of key performance indicators in a responsive metric grid.",
  "scenarios": [
    "Executive overview row",
    "Operations health board",
    "Marketing campaign summary"
  ],
  "props": {
    "items": {
      "type": "string",
      "required": true,
      "description": "Array of { id, label, value, trend? } metrics."
    },
    "label": {
      "type": "string",
      "required": false,
      "description": "Accessible label for the dashboard region."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "Grid populated with metrics."
    },
    {
      "name": "empty",
      "description": "No metrics provided."
    }
  ],
  "composition": {
    "allowedParents": [
      "page",
      "app-shell",
      "card"
    ],
    "allowedChildren": [
      "statistic"
    ],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not exceed eight KPI tiles in one dashboard.",
    "Do not mix unrelated units without labeling each tile."
  ],
  "a11y": {
    "role": "region",
    "keyboard": [],
    "focus": "Tiles are not focusable unless they contain actions.",
    "labeling": "Region label names the dashboard; each metric is a group.",
    "wcag": [
      "1.3.1"
    ]
  },
  "responsive": {
    "strategy": "Root sets container-type: inline-size; the grid is mobile-first compact (one column) and steps up via @container at token-equal rem thresholds. Not viewport @media.",
    "breakpoints": {
      "compact": "Single column (default; no query).",
      "medium": "Two columns at min-width 48rem (breakpoint.tablet).",
      "large": "Four columns at min-width 80rem (breakpoint.desktop)."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction inherits from document lang/dir.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "kpi-dashboard",
    "states": [
      "default",
      "empty"
    ],
    "intents": [
      "highlight-count",
      "group-content"
    ]
  }
}

import { Statistic } from '../statistic/index.js'
import './styles.css'

export interface KpiItem {
  id: string
  label: string
  value: string
  trend?: 'up' | 'down' | 'flat'
}

export interface KpiDashboardProps {
  items: KpiItem[]
  label?: string
  className?: string
}

export function KpiDashboard({ items, label = 'KPI dashboard', className }: KpiDashboardProps) {
  const classes = ['cu-kpi-dashboard', className].filter(Boolean).join(' ')
  return (
    <section
      className={classes}
      aria-label={label}
      data-ai-role="kpi-dashboard" data-ai-intent="highlight-count"
      data-ai-state={items.length === 0 ? 'empty' : 'default'}
    >
      <div className="cu-kpi-dashboard__grid">
        {items.map((item) => (
          <div key={item.id} className="cu-kpi-dashboard__tile">
            <Statistic label={item.label} value={item.value} trend={item.trend ?? 'flat'} trendLabel={item.trend} />
          </div>
        ))}
      </div>
    </section>
  )
}

/*
 * Query container: the dashboard root is the container; the grid consumes
 * it so columns follow the dashboard's own inline size (sidebar embed,
 * split view) rather than the viewport. Mobile-first compact is one column;
 * @container only enhances. 48rem == breakpoint.tablet, 80rem == breakpoint.desktop
 * (packages/tokens/src/core/breakpoint.json).
 */
.cu-kpi-dashboard {
  display: block;
  color: var(--cu-color-fg-default);
  container-type: inline-size;
}

.cu-kpi-dashboard__grid {
  display: grid;
  gap: var(--cu-space-3);
  grid-template-columns: minmax(0, 1fr);
}

.cu-kpi-dashboard__tile {
  padding-block: var(--cu-space-3);
  padding-inline: var(--cu-space-3);
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  background: var(--cu-color-background-default);
}

@container (min-width: 48rem) {
  .cu-kpi-dashboard__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@container (min-width: 80rem) {
  .cu-kpi-dashboard__grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}
